DROP TABLE IF EXISTS "geography_columns";
CREATE VIEW "geography_columns" AS SELECT current_database() AS f_table_catalog,
    n.nspname AS f_table_schema,
    c.relname AS f_table_name,
    a.attname AS f_geography_column,
    postgis_typmod_dims(a.atttypmod) AS coord_dimension,
    postgis_typmod_srid(a.atttypmod) AS srid,
    postgis_typmod_type(a.atttypmod) AS type
   FROM pg_class c,
    pg_attribute a,
    pg_type t,
    pg_namespace n
  WHERE ((t.typname = 'geography'::name) AND (a.attisdropped = false) AND (a.atttypid = t.oid) AND (a.attrelid = c.oid) AND (c.relnamespace = n.oid) AND (c.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char", 'f'::"char", 'p'::"char"])) AND (NOT pg_is_other_temp_schema(c.relnamespace)) AND has_table_privilege(c.oid, 'SELECT'::text));

DROP TABLE IF EXISTS "geometry_columns";
CREATE VIEW "geometry_columns" AS SELECT (current_database())::character varying(256) AS f_table_catalog,
    n.nspname AS f_table_schema,
    c.relname AS f_table_name,
    a.attname AS f_geometry_column,
    COALESCE(postgis_typmod_dims(a.atttypmod), sn.ndims, 2) AS coord_dimension,
    COALESCE(NULLIF(postgis_typmod_srid(a.atttypmod), 0), sr.srid, 0) AS srid,
    (replace(replace(COALESCE(NULLIF(upper(postgis_typmod_type(a.atttypmod)), 'GEOMETRY'::text), st.type, 'GEOMETRY'::text), 'ZM'::text, ''::text), 'Z'::text, ''::text))::character varying(30) AS type
   FROM ((((((pg_class c
     JOIN pg_attribute a ON (((a.attrelid = c.oid) AND (NOT a.attisdropped))))
     JOIN pg_namespace n ON ((c.relnamespace = n.oid)))
     JOIN pg_type t ON ((a.atttypid = t.oid)))
     LEFT JOIN ( SELECT s.connamespace,
            s.conrelid,
            s.conkey,
            replace(split_part(s.consrc, ''''::text, 2), ')'::text, ''::text) AS type
           FROM ( SELECT pg_constraint.connamespace,
                    pg_constraint.conrelid,
                    pg_constraint.conkey,
                    pg_get_constraintdef(pg_constraint.oid) AS consrc
                   FROM pg_constraint) s
          WHERE (s.consrc ~~* '%geometrytype(% = %'::text)) st ON (((st.connamespace = n.oid) AND (st.conrelid = c.oid) AND (a.attnum = ANY (st.conkey)))))
     LEFT JOIN ( SELECT s.connamespace,
            s.conrelid,
            s.conkey,
            (replace(split_part(s.consrc, ' = '::text, 2), ')'::text, ''::text))::integer AS ndims
           FROM ( SELECT pg_constraint.connamespace,
                    pg_constraint.conrelid,
                    pg_constraint.conkey,
                    pg_get_constraintdef(pg_constraint.oid) AS consrc
                   FROM pg_constraint) s
          WHERE (s.consrc ~~* '%ndims(% = %'::text)) sn ON (((sn.connamespace = n.oid) AND (sn.conrelid = c.oid) AND (a.attnum = ANY (sn.conkey)))))
     LEFT JOIN ( SELECT s.connamespace,
            s.conrelid,
            s.conkey,
            (replace(replace(split_part(s.consrc, ' = '::text, 2), ')'::text, ''::text), '('::text, ''::text))::integer AS srid
           FROM ( SELECT pg_constraint.connamespace,
                    pg_constraint.conrelid,
                    pg_constraint.conkey,
                    pg_get_constraintdef(pg_constraint.oid) AS consrc
                   FROM pg_constraint) s
          WHERE (s.consrc ~~* '%srid(% = %'::text)) sr ON (((sr.connamespace = n.oid) AND (sr.conrelid = c.oid) AND (a.attnum = ANY (sr.conkey)))))
  WHERE ((c.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char", 'f'::"char", 'p'::"char"])) AND (NOT (c.relname = 'raster_columns'::name)) AND (t.typname = 'geometry'::name) AND (NOT pg_is_other_temp_schema(c.relnamespace)) AND has_table_privilege(c.oid, 'SELECT'::text));

DROP TABLE IF EXISTS "your_table";
CREATE VIEW "your_table" AS WITH bnpl_invoices AS (
         SELECT i.id AS invoice_id,
            i.customer_id,
            i.car_id,
            i.auto_service_id,
            (i.created_at)::date AS bnpl_date,
            i.created_at AS bnpl_invoice_created_at
           FROM (invoices i
             JOIN auto_services s ON ((s.auto_service_id = i.auto_service_id)))
          WHERE (((i.status)::text = 'CONFIRMED'::text) AND (i.auto_service_id IS NOT NULL) AND ((s.city)::text = 'بیرجند'::text) AND ((i.source)::text = 'BNPL'::text) AND (i.created_at >= '2025-07-01 20:30:00+00'::timestamp with time zone))
        ), services AS (
         SELECT ms.created_at,
            ms.updated_at,
            ms.deleted_at,
            ms.service_id,
            ms.brand,
            ms.model,
            ms.date_of_change,
            ms.km_of_change,
            ms.next_km,
            ms.description,
            ms.details,
            ms.total_cost,
            ms.auto_service_id,
            ms.car_id,
            ms.customer_id,
            ms.deleted_by_id,
            ms.type_id,
            ms.supplier_id,
            ms.next_date,
            ms.car_km_difference,
            ms.source,
            COALESCE((ms.date_of_change)::timestamp with time zone, ms.created_at) AS svc_date
           FROM maintanence_services ms
          WHERE ((ms.auto_service_id IS NOT NULL) AND (ms.car_id IN ( SELECT DISTINCT bnpl_invoices.car_id
                   FROM bnpl_invoices)))
        )
 SELECT sv.car_id,
    asv.name AS auto_service_name,
    mst.name AS service_type_name,
    sv.brand,
    sv.model,
    ( WITH g AS (
                 SELECT (EXTRACT(year FROM sv.svc_date))::integer AS gy,
                    (EXTRACT(month FROM sv.svc_date))::integer AS gm,
                    (EXTRACT(day FROM sv.svc_date))::integer AS gd
                ), base AS (
                 SELECT g.gy,
                    g.gm,
                    g.gd,
                    (g.gy - 1600) AS y,
                    (g.gm - 1) AS m,
                    (g.gd - 1) AS d,
                        CASE
                            WHEN ((((g.gy % 4) = 0) AND ((g.gy % 100) <> 0)) OR ((g.gy % 400) = 0)) THEN 1
                            ELSE 0
                        END AS is_leap
                   FROM g
                ), days_y AS (
                 SELECT base.gy,
                    base.gm,
                    base.is_leap,
                    base.d,
                    base.m,
                    ((((365 * (base.gy - 1600)) + (((base.gy - 1600) + 3) / 4)) - (((base.gy - 1600) + 99) / 100)) + (((base.gy - 1600) + 399) / 400)) AS dy
                   FROM base
                ), month_acc AS (
                 SELECT days_y.gy,
                    days_y.gm,
                    days_y.is_leap,
                    days_y.d,
                    (days_y.dy +
                        CASE days_y.m
                            WHEN 0 THEN 0
                            WHEN 1 THEN 31
                            WHEN 2 THEN 59
                            WHEN 3 THEN 90
                            WHEN 4 THEN 120
                            WHEN 5 THEN 151
                            WHEN 6 THEN 181
                            WHEN 7 THEN 212
                            WHEN 8 THEN 243
                            WHEN 9 THEN 273
                            WHEN 10 THEN 304
                            WHEN 11 THEN 334
                            ELSE NULL::integer
                        END) AS dy_m
                   FROM days_y
                ), greg_day_no AS (
                 SELECT ((month_acc.dy_m + month_acc.d) +
                        CASE
                            WHEN ((month_acc.gm > 2) AND (month_acc.is_leap = 1)) THEN 1
                            ELSE 0
                        END) AS g_day_no
                   FROM month_acc
                ), j_prep AS (
                 SELECT (greg_day_no.g_day_no - 79) AS j_day_no
                   FROM greg_day_no
                ), j_cycle AS (
                 SELECT (j_prep.j_day_no / 12053) AS j_np,
                    (j_prep.j_day_no % 12053) AS j_rem
                   FROM j_prep
                ), j_year AS (
                 SELECT ((979 + (33 * j_cycle.j_np)) + (4 * (j_cycle.j_rem / 1461))) AS jy_tmp,
                    (j_cycle.j_rem % 1461) AS r2
                   FROM j_cycle
                ), j_norm AS (
                 SELECT
                        CASE
                            WHEN (j_year.r2 >= 366) THEN (j_year.jy_tmp + ((j_year.r2 - 1) / 365))
                            ELSE j_year.jy_tmp
                        END AS jy,
                        CASE
                            WHEN (j_year.r2 >= 366) THEN ((j_year.r2 - 1) % 365)
                            ELSE j_year.r2
                        END AS j_day_no2
                   FROM j_year
                ), j_md AS (
                 SELECT j_norm.jy,
                        CASE
                            WHEN (j_norm.j_day_no2 < 186) THEN ((j_norm.j_day_no2 / 31) + 1)
                            ELSE (((j_norm.j_day_no2 - 186) / 30) + 7)
                        END AS jm,
                        CASE
                            WHEN (j_norm.j_day_no2 < 186) THEN ((j_norm.j_day_no2 % 31) + 1)
                            ELSE (((j_norm.j_day_no2 - 186) % 30) + 1)
                        END AS jd
                   FROM j_norm
                )
         SELECT ((((lpad((j_md.jy)::text, 4, '0'::text) || '-'::text) || lpad((j_md.jm)::text, 2, '0'::text)) || '-'::text) || lpad((j_md.jd)::text, 2, '0'::text))
           FROM j_md) AS service_date_jalali,
    (sv.km_of_change)::numeric AS km_of_change,
    (sv.total_cost)::numeric AS total_cost,
    row_number() OVER (PARTITION BY sv.car_id ORDER BY sv.svc_date, sv.created_at) AS service_seq,
    bi.invoice_id AS bnpl_invoice_id,
    bi.bnpl_invoice_created_at,
    (bi.invoice_id IS NOT NULL) AS is_bnpl
   FROM (((services sv
     JOIN auto_services asv ON ((sv.auto_service_id = asv.auto_service_id)))
     LEFT JOIN maintanence_service_types mst ON ((sv.type_id = mst.type_id)))
     LEFT JOIN LATERAL ( SELECT b.invoice_id,
            b.bnpl_invoice_created_at
           FROM bnpl_invoices b
          WHERE ((b.car_id = sv.car_id) AND (b.auto_service_id = sv.auto_service_id))
          ORDER BY (abs(EXTRACT(epoch FROM (sv.svc_date - b.bnpl_invoice_created_at))))
         LIMIT 1) bi ON (true));

